/**
 * @param {number[]} arr
 * @param {Function} fn
 * @return {number[]}
 */
var map = function(arr, fn) {
    // Pre-size the result so results[i] lines up with arr[i]
    const res = new Array(arr.length);
    // Iterate over each index of arr
    for (let i = 0; i < arr.length; i++) {
        // Apply the mapping function to the value and its index
        res[i] = fn(arr[i], i);
    }
    return res;
};
